import{_ as o,o as a,c as s,a2 as t}from"./chunks/framework.D7Ov6LBE.js";const m=JSON.parse('{"title":"supabaseAndFiscal.ts — DDL e Motor Fiscal","description":"","frontmatter":{},"headers":[],"relativePath":"componentes/supabase-fiscal.md","filePath":"componentes/supabase-fiscal.md","lastUpdated":1786474711000}'),d={name:"componentes/supabase-fiscal.md"};function c(i,e,l,r,n,p){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="supabaseandfiscal-ts-—-ddl-e-motor-fiscal" tabindex="-1">supabaseAndFiscal.ts — DDL e Motor Fiscal <a class="header-anchor" href="#supabaseandfiscal-ts-—-ddl-e-motor-fiscal" aria-label="Permalink to &quot;supabaseAndFiscal.ts — DDL e Motor Fiscal&quot;">​</a></h1><p><strong>Arquivo:</strong> <code>src/utils/supabaseAndFiscal.ts</code> · <strong>Símbolos codegraph:</strong> 6 · <strong>Licença:</strong> Apache-2.0</p><h2 id="responsabilidades" tabindex="-1">Responsabilidades <a class="header-anchor" href="#responsabilidades" aria-label="Permalink to &quot;Responsabilidades&quot;">​</a></h2><p>Duas frentes: geração do <strong>schema SQL do Supabase</strong> e o <strong>motor fiscal</strong> (chave NF-e, protocolo, XML).</p><h2 id="_1-generatesupabasesqlschema" tabindex="-1">1. <code>generateSupabaseSqlSchema()</code> <a class="header-anchor" href="#_1-generatesupabasesqlschema" aria-label="Permalink to &quot;1. `generateSupabaseSqlSchema()`&quot;">​</a></h2><p>Gera o DDL completo (copy-paste no SQL Editor do Supabase) com as 5 tabelas:</p><ol><li><code>public.clientes</code> — PF/PJ, <code>cpf_cnpj UNIQUE</code>, limite/uso de crédito, endereço fiscal.</li><li><code>public.produtos</code> — catálogo com SKU único, NCM, estoque, <code>is_service</code>.</li><li><code>public.condicoes_pagamento</code> — PIX, boleto 30/60/90, cartão, faturado ERP (com <code>INSERT ... ON CONFLICT DO NOTHING</code>).</li><li><code>public.pedidos</code> — mestre com <code>codigo_pedido UNIQUE</code>, <code>status_sync</code>, <code>status_fiscal</code>, chave/protocolo NF-e, <code>assinatura_base64</code>.</li><li><code>public.pedido_itens</code> — 1:N com <code>ON DELETE CASCADE</code> para o pedido.</li></ol><h2 id="_2-motor-fiscal-client-side" tabindex="-1">2. Motor fiscal (client-side) <a class="header-anchor" href="#_2-motor-fiscal-client-side" aria-label="Permalink to &quot;2. Motor fiscal (client-side)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Função</th><th>O que gera</th></tr></thead><tbody><tr><td><code>generateNfeAccessKey()</code></td><td><strong>Chave de acesso de 44 dígitos</strong> SEFAZ: UF + emissão + CNPJ + modelo 55 + série + número + tpEmis + código numérico + <strong>DV módulo 11 (pesos 2–9)</strong></td></tr><tr><td><code>generateProtocoloNfe()</code></td><td>Protocolo de autorização de uso no padrão SEFAZ</td></tr><tr><td><code>generateOrderErpXml(order)</code></td><td>XML v4.00 do pedido no schema <code>http://www.amplavendas.eng.br/schema/erp/v2</code> — consumido pelo <code>LoteIntegracaoERP</code> e pelos adaptadores ERP</td></tr></tbody></table><h2 id="fluxo-de-uso" tabindex="-1">Fluxo de uso <a class="header-anchor" href="#fluxo-de-uso" aria-label="Permalink to &quot;Fluxo de uso&quot;">​</a></h2><ol><li><code>DanfeNfeModal</code> chama <code>generateNfeAccessKey()</code> ao emitir DANFE.</li><li><code>MainApp.handleExportAllXml</code> chama <code>generateOrderErpXml()</code> por pedido e monta o lote.</li><li>A UI do Supabase (painel) recebe o DDL de <code>generateSupabaseSqlSchema()</code>.</li></ol><h2 id="notas-de-engenharia" tabindex="-1">Notas de engenharia <a class="header-anchor" href="#notas-de-engenharia" aria-label="Permalink to &quot;Notas de engenharia&quot;">​</a></h2><ul><li><strong>Tudo client-side</strong>: emissão e chaveamento fiscal funcionam offline — requisito central do produto.</li><li><strong>DV módulo 11</strong> implementado manualmente (sem lib fiscal) — algoritmo padrão SEFAZ.</li><li>DDL <strong>idempotente</strong> (<code>IF NOT EXISTS</code>, <code>ON CONFLICT</code>) — reexecutável sem erros.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="./../arquitetura/modulo-fiscal">Módulo Fiscal</a></li><li><a href="./danfe-nfe-modal">DanfeNfeModal</a></li><li><a href="./../arquitetura/modelo-dados-supabase">Modelo de Dados &amp; Supabase</a></li></ul>',15)])])}const h=o(d,[["render",c]]);export{m as __pageData,h as default};
